changeSet.sql:
ALTER TABLE achievement_definitions
ADD CONSTRAINT chk_achievement_category CHECK (category IN ('milestone', 'skill', 'social', 'event', 'streak'));
ALTER TABLE achievement_definitions
ADD CONSTRAINT chk_achievement_tier CHECK (tier IN ('bronze', 'silver', 'gold', 'platinum'));

CREATE POLICY achievement_definitions_select_all ON achievement_definitions
    FOR SELECT
    USING (is_active = true);

CREATE POLICY player_achievements_select_public ON player_achievements
    FOR SELECT
    USING (true);

changeSet.rollback:
DELETE FROM achievement_definitions WHERE key IN (
    'tournament_winner', 'tournament_runner_up', 'tournament_third',
    'multi_champion', 'open_play_leader'
);
